begin;
update public.questions set subject = 'Environment & Ecology', topic = 'Ecosystems & Ecological Processes', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about wetlands:', body_hi = 'आर्द्रभूमियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. The Ramsar definition is broad: marshes, fens, peatlands or water, natural or artificial, permanent or temporary, static or flowing, fresh, brackish or salt, and shallow marine waters. In peatlands, waterlogging slows decomposition so much that dead plant matter piles up as peat over thousands of years; they hold nearly a third of the world''s soil carbon -- about twice that of all forests. Statement 3 is wrong: draining lets air into the peat, which then decomposes and releases its carbon as carbon dioxide, and dry peat burns easily, so drained and burning peatlands are large sources of emissions. Wetlands also act like sponges, storing floodwater and releasing it slowly, recharge aquifers, and filter sediments and pollutants.', explanation_hi = 'कथन 1 और 2 सही हैं। रामसर परिभाषा व्यापक है: दलदल, फ़ेन, पीटभूमि या जल -- प्राकृतिक या कृत्रिम, स्थायी या अस्थायी, स्थिर या बहता, मीठा, खारा या लवणीय -- और उथला समुद्री जल। पीटभूमियों में जलमग्नता अपघटन को इतना धीमा कर देती है कि मृत पादप पदार्थ हज़ारों वर्षों में पीट के रूप में जमा होता जाता है; इनमें विश्व के मृदा कार्बन का लगभग एक-तिहाई -- सभी वनों का लगभग दोगुना -- है। कथन 3 गलत है: सुखाने से पीट में हवा पहुँचती है, जिससे वह अपघटित होकर अपना कार्बन कार्बन डाइऑक्साइड के रूप में छोड़ती है, और सूखी पीट आसानी से जलती है, इसलिए सुखाई गई और जलती पीटभूमियाँ उत्सर्जन के बड़े स्रोत हैं। आर्द्रभूमियाँ स्पंज की तरह बाढ़ का पानी रोककर धीरे-धीरे छोड़ती भी हैं, जलभृतों का पुनर्भरण करती हैं, और तलछट तथा प्रदूषकों को छानती हैं।', concept_group_id = 'l1-rev-wetland-definition-peatlands', source_citation = 'Ramsar Convention on Wetlands (1971), Article 1; UNEP, Global Peatlands Assessment (2022).', question_data = '{"statements": ["Under the Ramsar Convention''s definition, areas of marine water count as wetlands where the depth at low tide does not exceed six metres.", "Peatlands cover only about 3 per cent of the world''s land surface but store more carbon than all the world''s forests combined.", "Draining a peatland for farming locks its carbon away more securely."], "statements_hi": ["रामसर अभिसमय की परिभाषा में समुद्री जल के वे क्षेत्र आर्द्रभूमि माने जाते हैं जहाँ भाटे के समय गहराई छह मीटर से अधिक न हो।", "पीटभूमियाँ (peatlands) विश्व की स्थल सतह के केवल लगभग 3 प्रतिशत भाग पर हैं, पर विश्व के सभी वनों को मिलाकर जितना कार्बन है उससे अधिक संचित करती हैं।", "खेती के लिए पीटभूमि को सुखाने से उसका कार्बन और सुरक्षित रूप से बंद हो जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l1-rev-wetland-definition-peatlands' returning concept_group_id;
commit;
